// Baustein 1: Mail bereinigen (v0.2)
// - erkennt manuell weitergeleitete Mails (Fwd/WG) und nutzt den Originalteil
// - schneidet bei Patreon-Mails (DE/EN) Kopfbereich und Footer ab
// - entfernt Füllzeichen, Bild-Links, Tracking und harte Zeilenumbrüche
// - liest Veröffentlichungsdatum, Titel, Ticker und Beitrags-URL aus

const FORWARD_MARKER = /-{3,}\s*(Forwarded message|Weitergeleitete Nachricht|Original Message|Ursprüngliche Nachricht)\s*-{3,}/i;
// Ende des Beitragskopfs: letzte "In der App anzeigen"/"View in app"-Zeile inkl. Link-Zeile
const HEADER_END = /^(In der App anzeigen|View in app|Open in app)\s*\n\[[^\]]*\]\s*$/gim;
// Beginn des Footers (erste Fundstelle zählt)
const FOOTER_MARKERS = [
  /^\s*HAT DIR DIESER POST GEFALLEN\??/im,
  /^\s*DID YOU (ENJOY|LIKE) THIS POST\??/im,
  /^\s*Teile diesen Post\b/im,
  /^\s*Share this post\b/im,
  /^\s*©\s*\d{4}\b/m,
  /^\s*(Abbestellen|Unsubscribe)\b/im,
  /E-Mail wurde an .* gesendet/i,
  /This email was sent to/i,
];
const MONTHS = { jan:1, feb:2, 'mär':3, mar:3, apr:4, mai:5, may:5, jun:6, jul:7, aug:8, sep:9, okt:10, oct:10, nov:11, dez:12, dec:12 };

function htmlToText(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h[1-6]|tr)>/gi, '\n\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#39;|&rsquo;/g, '’').replace(/&quot;/g, '"');
}

function headerValue(block, names) {
  for (const name of names) {
    const m = block.match(new RegExp('^\\s*\\*?' + name + '\\*?:\\s*(.+)$', 'im'));
    if (m) return m[1].trim();
  }
  return '';
}

function removeInvisible(text) {
  // Füllzeichen aus E-Mail-Vorschauen: CGJ, Soft Hyphen, Zero-Width, Figure Space, BOM
  return text.replace(/[͏­​-‍ ⁠﻿]/g, '');
}

function parseDate(text) {
  // "30. Okt. 2026" | "30 Oct 2026" | "Oct 30, 2026"
  let m = text.match(/^\s*(\d{1,2})\.?\s+([A-Za-zÄÖÜäöü]{3,})\.?\s+(\d{4})\s*$/m);
  let d, mo, y;
  if (m) { d = +m[1]; mo = MONTHS[m[2].slice(0, 3).toLowerCase()]; y = +m[3]; }
  else {
    m = text.match(/^\s*([A-Za-z]{3,})\.?\s+(\d{1,2}),\s+(\d{4})\s*$/m);
    if (m) { d = +m[2]; mo = MONTHS[m[1].slice(0, 3).toLowerCase()]; y = +m[3]; }
  }
  if (!m || !mo) return '';
  return `${y}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function berlinDate(iso) {
  if (!iso) return '';
  const dt = new Date(iso);
  if (isNaN(dt)) return '';
  return dt.toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' }); // YYYY-MM-DD
}

function cutFooter(text) {
  let cut = text.length;
  for (const re of FOOTER_MARKERS) {
    const m = re.exec(text);
    if (m && m.index < cut && m.index > 20) cut = m.index;
  }
  return text.slice(0, cut);
}

function cleanBody(text) {
  return text
    .replace(/^\s*\[https?:\/\/[^\]]*\]\s*\S*\s*$/gim, '')   // Bildzeilen "[https://...png]link"
    .replace(/\[https?:\/\/[^\]]*\]/g, '')                    // übrige Link-Klammern
    .replace(/(https?:\/\/[^\s<>()\]]+)\?[^\s<>()\]]*/g, '$1') // Tracking-Parameter
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .split(/\n\s*\n/)                                          // Absätze
    .map(p => p.replace(/\s*\n\s*/g, ' ').trim())              // harte Umbrüche entfernen
    .filter(Boolean)
    .join('\n\n')
    .trim();
}

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  let raw = (m.text && String(m.text).trim()) ? String(m.text) : htmlToText(m.html);
  raw = removeInvisible(raw).replace(/\r/g, '');

  let isForwarded = false;
  let origFrom = (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || '';
  let origDateRaw = m.date || '';
  let origSubject = String(m.subject || '');

  const fwd = FORWARD_MARKER.exec(raw);
  if (fwd) {
    isForwarded = true;
    const after = raw.slice(fwd.index + fwd[0].length);
    const split = after.match(/^([\s\S]*?\n\s*\n)([\s\S]*)$/);
    const headerBlock = split ? split[1] : '';
    raw = split ? split[2] : after;
    origFrom = headerValue(headerBlock, ['From', 'Von']) || origFrom;
    origDateRaw = headerValue(headerBlock, ['Date', 'Datum', 'Gesendet', 'Sent']) || origDateRaw;
    origSubject = headerValue(headerBlock, ['Subject', 'Betreff']) || origSubject;
  }

  // Kopfbereich (Vorschau, Titel, Autor, Datum, Like/Comment/Share) abschneiden
  let body = raw;
  let headerPart = '';
  let lastHeaderEnd = -1;
  for (const hm of raw.matchAll(HEADER_END)) lastHeaderEnd = hm.index + hm[0].length;
  if (lastHeaderEnd > -1) { headerPart = raw.slice(0, lastHeaderEnd); body = raw.slice(lastHeaderEnd); }
  body = cleanBody(cutFooter(body));

  const subject = origSubject.replace(/^\s*((fwd?|fw|wg|aw|re)\s*:\s*)+/i, '').trim();
  const tickerMatch = subject.match(/\$([A-Z][A-Z0-9.]{0,6})\b/) || body.match(/\$([A-Z][A-Z0-9.]{0,6})\b/);
  const postUrl = (raw.match(/https?:\/\/(?:www\.)?patreon\.com\/(?:[\w-]+\/)?posts\/[\w-]+/i) || [''])[0];
  const datePost = parseDate(headerPart || raw);
  const dateFallback = berlinDate(isForwarded ? origDateRaw : m.date);

  const errors = [];
  if (!body || body.length < 80) errors.push('Beitragstext fehlt oder ist zu kurz');
  if (!/patreon/i.test(origFrom + postUrl)) errors.push('Absender/Link ist nicht Patreon');

  out.push({
    json: {
      gmail_message_id: m.id,
      gmail_thread_id: m.threadId,
      email_date: m.date || '',
      is_forwarded: isForwarded,
      original_from: origFrom,
      published_date: datePost || dateFallback,
      date_status: datePost ? 'aus_beitrag' : (dateFallback ? 'aus_email_datum' : 'unbekannt'),
      subject,
      ticker_hint: tickerMatch ? tickerMatch[1] : '',
      post_url: postUrl,
      body_clean: body,
      body_words: body ? body.split(/\s+/).length : 0,
      ok: errors.length === 0,
      errors,
    },
  });
}
return out;

// Baustein 2a: Anfrage an Claude bauen (v0.3)
// Claude muss über ein "Werkzeug" antworten -> die Antwort ist garantiert ein JSON-Objekt nach Schema.

const MODEL = 'claude-haiku-5-5';
const PROMPT_VERSION = 'analyst-extraction-v2';

const SYSTEM = `Du bist ein Extraktionssystem für Analystenbeiträge zu Wertpapieren. Du erhältst einen Patreon-Beitrag des Analysten "The Long Investor" und rufst genau einmal das Werkzeug "analyse_speichern" mit den extrahierten Daten auf.

Regeln:
1. Übernimm nur Informationen, die im Beitrag ausdrücklich stehen. Erfinde keine Kursmarken, Spannen, Daten, Unternehmensnamen oder Zeithorizonte.
2. Fehlt eine wichtige Angabe (Invalidierung, Kursziel, Zeithorizont), nenne sie in "missing_information" (höchstens 4 Einträge). Sonst "", [] oder null.
3. Rollen von Kursmarken nur zuordnen, wenn der Text die Rolle ausdrücklich nennt:
   - supports: "support", "Unterstützung", "holding $X", "buyers step in"
   - resistances: "resistance", "Widerstand", "break above $X"
   - invalidations: "invalidation", "invalidates", "count fails below"
   - targets: "target", "Ziel", "Bull Case", "Bear Case" (Label entsprechend)
   - observation_zones: "buy zone", "accumulation zone", "attractive to add/buy". Eine einzelne Marke als from = to. Spannen nur, wenn der Text beide Grenzen nennt.
   Alle anderen genannten Marken (aktueller Kurs, frühere Hochs/Tiefs, verlorene oder zurückeroberte Durchschnitte) gehören in "other_levels" mit kurzer Rollenbeschreibung.
4. Eine Marke darf in mehreren Feldern stehen, wenn der Text ihr mehrere Rollen gibt (z. B. Invalidierung und "holding $143").
5. Das Haupt-Wertpapier ist das im Betreff genannte. Andere Ticker im Text gehören nur in "mentioned_tickers" (ohne $).
6. Kursziele, Konsens oder Einschätzungen anderer Analysten sind keine Ziele von The Long Investor: in "fundamental_statements".
7. Termine wie Earnings oder Hauptversammlungen in "upcoming_events" (Datum wie im Text).
8. "WMA" = Weekly Moving Average, "Day MA" = Daily Moving Average, "PM" = Premarket. Fib-Verhältnisse wie im Original schreiben (z. B. "0.618 Fib"). Monatsangaben ohne Jahr bleiben ohne Jahr.
9. Kurz und ohne Wiederholungen: "summary" höchstens 3 Sätze; jedes andere Textfeld höchstens 1 Satz; "note" höchstens 8 Wörter oder leer. Dieselbe Information nicht in mehreren Textfeldern wiederholen.
10. Alle Texte auf Deutsch, sachlich, als Einschätzung des Analysten. Keine eigene Bewertung, keine Empfehlung.
11. recognized_concepts: höchstens 8 Fachbegriffe aus dem Beitrag in deutscher Standardbezeichnung (z. B. "Elliott-Wellen", "Fibonacci-Retracement", "Gleitender Durchschnitt", "Invalidierung").`;

const level = {
  type: 'object',
  properties: {
    level: { type: ['number', 'null'] },
    currency: { type: 'string' },
    label: { type: 'string' },
    note: { type: 'string' },
  },
  required: ['level', 'label'],
};
const zone = {
  type: 'object',
  properties: {
    from: { type: ['number', 'null'] },
    to: { type: ['number', 'null'] },
    currency: { type: 'string' },
    label: { type: 'string' },
  },
  required: ['from', 'to', 'label'],
};
const strings = { type: 'array', items: { type: 'string' } };

const TOOL = {
  name: 'analyse_speichern',
  description: 'Speichert die strukturierte Analyse des Beitrags.',
  input_schema: {
    type: 'object',
    properties: {
      ticker: { type: 'string', description: 'Haupt-Ticker ohne $' },
      main_category: { type: 'string', enum: ['Technisch', 'Fundamental', 'Sonstige'] },
      analysis_types: { type: 'array', items: { type: 'string', enum: ['technisch', 'fundamental', 'makro', 'sonstige'] } },
      time_horizon: { type: 'string' },
      summary: { type: 'string' },
      market_state: { type: 'string' },
      primary_scenario: { type: 'string' },
      alternative_scenario: { type: 'string' },
      supports: { type: 'array', items: level },
      resistances: { type: 'array', items: level },
      observation_zones: { type: 'array', items: zone },
      invalidations: { type: 'array', items: level },
      targets: { type: 'array', items: level },
      other_levels: { type: 'array', items: level },
      elliott_wave: { type: 'string' },
      trend_structure: { type: 'string' },
      fundamental_statements: strings,
      upcoming_events: strings,
      reevaluation_conditions: strings,
      changes_stated_by_analyst: { type: 'string' },
      uncertainties_and_risks: strings,
      mentioned_tickers: strings,
      missing_information: strings,
      recognized_concepts: strings,
    },
    required: ['ticker', 'main_category', 'analysis_types', 'summary', 'supports', 'resistances',
      'observation_zones', 'invalidations', 'targets', 'missing_information', 'recognized_concepts'],
  },
};

return $input.all().map(item => {
  const p = item.json;
  const user = [
    `Betreff: ${p.subject}`,
    `Haupt-Ticker laut Betreff: ${p.ticker_hint || 'unbekannt'}`,
    `Veröffentlicht: ${p.published_date || 'unbekannt'}`,
    '',
    'Beitrag:',
    p.body_clean,
  ].join('\n');

  return {
    json: {
      ...p,
      model: MODEL,
      prompt_version: PROMPT_VERSION,
      request: {
        model: MODEL,
        max_tokens: 4000,
        system: SYSTEM,
        tools: [TOOL],
        tool_choice: { type: 'tool', name: 'analyse_speichern' },
        messages: [{ role: 'user', content: user }],
      },
    },
  };
});

// Baustein 2b: Antwort von Claude prüfen (v0.3)
// Holt das JSON aus der Werkzeug-Antwort, normalisiert sicher Normalisierbares
// und prüft die Regeln aus dem Datenvertrag. Ergebnis: ok=true/false + errors/warnings.

const PRICE_IN = 0.10 / 1e6;   // Haiku 5.5, USD pro Input-Token (Prompt < 100k)
const PRICE_OUT = 0.50 / 1e6;  // USD pro Output-Token
const CATEGORIES = ['Technisch', 'Fundamental', 'Sonstige'];

const sources = $('Prompt bauen').all();

return $input.all().map((item, i) => {
  const res = item.json;
  const src = sources[i] ? sources[i].json : {};
  const { request, ...meta } = src;
  const errors = [];
  const warnings = [];

  const toolUse = (res.content || []).find(c => c.type === 'tool_use');
  let a = toolUse ? toolUse.input : null;
  if (!a || typeof a !== 'object') {
    errors.push('Keine strukturierte Antwort von Claude erhalten');
    a = {};
  }

  // --- sicher normalisierbar ---
  const arr = v => Array.isArray(v) ? v : (v == null || v === '' ? [] : [v]);
  for (const k of ['analysis_types', 'supports', 'resistances', 'observation_zones', 'invalidations', 'targets', 'other_levels',
    'fundamental_statements', 'upcoming_events', 'reevaluation_conditions', 'uncertainties_and_risks',
    'mentioned_tickers', 'missing_information', 'recognized_concepts']) a[k] = arr(a[k]);
  a.ticker = String(a.ticker || '').replace(/^\$/, '').trim().toUpperCase();
  a.mentioned_tickers = a.mentioned_tickers.map(t => String(t).replace(/^\$/, '').toUpperCase()).filter(t => t && t !== a.ticker);
  if (a.main_category) {
    const c = String(a.main_category).trim();
    a.main_category = CATEGORIES.find(x => x.toLowerCase() === c.toLowerCase()) || c;
  }
  for (const k of ['supports', 'resistances', 'invalidations', 'targets', 'other_levels']) {
    a[k] = a[k].map(l => ({ ...l, level: (l && l.level != null && l.level !== '') ? Number(l.level) : null, currency: (l && l.currency) || (l && l.level != null ? 'USD' : '') }));
  }

  // --- Pflichtprüfungen ---
  if (!CATEGORIES.includes(a.main_category)) errors.push(`Unbekannte Kategorie: ${a.main_category}`);
  if (['Technisch', 'Fundamental'].includes(a.main_category) && !/^[A-Z][A-Z0-9.]{0,6}$/.test(a.ticker)) errors.push(`Ungültiger oder fehlender Ticker: "${a.ticker}"`);
  if (!a.summary) errors.push('Zusammenfassung fehlt');
  for (const k of ['supports', 'resistances', 'invalidations', 'targets']) {
    a[k].forEach((l, j) => { if (l.level !== null && !Number.isFinite(l.level)) errors.push(`${k}[${j}]: Kurs ist keine Zahl`); });
  }

  // --- Warnungen (kein Abbruch, aber im Review sichtbar) ---
  if (meta.ticker_hint && a.ticker && meta.ticker_hint !== a.ticker) warnings.push(`Ticker weicht vom Betreff ab: Betreff ${meta.ticker_hint}, Claude ${a.ticker}`);
  const body = String(meta.body_clean || '');
  const allLevels = ['supports', 'resistances', 'invalidations', 'targets', 'other_levels'].flatMap(k => a[k].map(l => l.level)).filter(v => v !== null);
  for (const v of allLevels) {
    const plain = String(v);
    const withComma = plain.replace('.', ',');
    if (!body.includes(plain) && !body.includes(withComma)) warnings.push(`Kursmarke ${v} kommt im Originaltext nicht wörtlich vor – bitte prüfen`);
  }
  for (const z of a.observation_zones) for (const v of [z.from, z.to]) {
    if (v != null && !body.includes(String(v)) && !body.includes(String(v).replace('.', ','))) warnings.push(`Zonengrenze ${v} kommt im Originaltext nicht wörtlich vor – bitte prüfen`);
  }
  const lv = k => new Set(a[k].map(l => l.level).filter(v => v !== null));
  for (const v of lv('supports')) if (lv('resistances').has(v)) warnings.push(`Kursmarke ${v} ist gleichzeitig Unterstützung und Widerstand`);
  if (res.stop_reason === 'max_tokens') errors.push('Antwort von Claude wurde abgeschnitten (max_tokens)');

  const usage = res.usage || {};
  const cost = (usage.input_tokens || 0) * PRICE_IN + (usage.output_tokens || 0) * PRICE_OUT;

  return {
    json: {
      ...meta,
      ok: errors.length === 0 && meta.ok !== false,
      errors: [...(meta.errors || []), ...errors],
      warnings,
      analysis: a,
      usage: { input_tokens: usage.input_tokens || 0, output_tokens: usage.output_tokens || 0, cost_usd: Number(cost.toFixed(6)), cost_cent: Number((cost * 100).toFixed(4)) },
    },
  };
});
